// TypeScript Version: 4.1

/**
* Evaluates the quantile function for a Half-normal distribution.
*
* @param p - cumulative probability
* @returns evaluated quantile
*/
type Unary = ( p: number ) => number;

/**
* Interface for the quantile function of a Half-normal distribution.
*/
interface Quantile {
	/**
	* Evaluates the quantile function for a Half-normal distribution with scale parameter `sigma`.
	*
	* ## Notes
	*
	* -   If `sigma < 0`, the function returns `NaN`.
	* -   If `p < 0` or `p > 1`, the function returns `NaN`.
	* -   If `sigma = 0`, the function returns `0`.
	* -   If `p = 1`, the function returns `+Infinity`.
	*
	* @param p - cumulative probability
	* @param sigma - scale parameter
	* @returns evaluated quantile
	*
	* @example
	* var y = quantile( 0.8, 1.0 );
	* // returns ~1.2816
	*
	* @example
	* var y = quantile( 0.5, 2.0 );
	* // returns ~1.3490
	*
	* @example
	* var y = quantile( 1.1, 1.0 );
	* // returns NaN
	*
	* @example
	* // Negative scale parameter:
	* var y = quantile( 0.5, -1.0 );
	* // returns NaN
	*/
	( p: number, sigma: number ): number;

	/**
	* Returns a function for evaluating the quantile function for a Half-normal distribution with scale parameter `sigma`.
	*
	* @param sigma - scale parameter
	* @returns quantile function
	*
	* @example
	* var myquantile = quantile.factory( 2.0 );
	* var y = myquantile( 0.5 );
	* // returns ~1.3490
	*/
	factory( sigma: number ): Unary;
}

/**
* Half-normal distribution quantile function.
*
* @param p - cumulative probability
* @param sigma - scale parameter
* @returns evaluated quantile
*
* @example
* var y = quantile( 0.8, 1.0 );
* // returns ~1.2816
*
* var myquantile = quantile.factory( 1.0 );
* var y = myquantile( 0.8 );
* // returns ~1.2816
*/
declare var quantile: Quantile;


// EXPORTS //

export = quantile;
